{% if customer.b2b? %}
  <span class="price">{{ variant.price | money }}</span>
  {% if variant.compare_at_price > variant.price %}
    <s>{{ variant.compare_at_price | money }}</s>
  {% endif %}
{% endif %}

{% if variant.quantity_price_breaks.size > 0 %}
  <table>
    <tr><th>Quantidade</th><th>Preço unitário</th></tr>
    {% for break in variant.quantity_price_breaks %}
      <tr>
        <td>{{ break.minimum_quantity }}+</td>
        <td>{{ break.price | money }}</td>
      </tr>
    {% endfor %}
  </table>
{% endif %}

// busca só o bloco de preço já renderizado pelo servidor
const url = `${location.pathname}?variant=${variantId}&section_id=${sectionId}`;
const html = await (await fetch(url)).text();
const doc = new DOMParser().parseFromString(html, "text/html");
document.querySelector("#price").replaceWith(doc.querySelector("#price"));
